/** Refuses unless the actor is the recorded owner, which the owner role alone does not establish. */
function assertRecordedOwner(actor: Actor, organization: Organization): void {
  if (organization.ownerId === actor.userId) return;

  throw new PermissionDeniedError("org:manage_billing", {
    action: "org:manage_billing",
    resourceKind: "organization",
    allowed: false,
    reason: "denied_by_role",
  });
}

function isLapsed(handover: OwnershipHandover, now: Date): boolean {
  return Date.parse(handover.expiresAt) <= now.getTime();
}

/**
 * The open offer the actor may act on. A lapsed offer is not open: the
 * offered member gets `expired` for accept/decline, everyone else
 * `nothing_pending`, and nothing is written.
 */
async function requireActionableHandover(
  orgId: OrgId,
  userId: UserId,
  asRecipient: boolean,
): Promise<OwnershipHandover> {
  const open = await handoverRepo.findPendingHandover(orgId);
  if (!open || (asRecipient && open.toUserId !== userId)) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  if (isLapsed(open, new Date())) {
    throw new OwnershipHandoverError(asRecipient ? "expired" : "nothing_pending");
  }

  return open;
}

